begin;
-- Sprint 41 - Inteligencia executiva, indicadores, alertas e governanca
create table if not exists intelligence_dashboards(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),name varchar(160) not null,description text,visibility varchar(20) not null default 'PRIVATE' check(visibility in('PRIVATE','TEAM','TENANT')),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,unique(tenant_id,id));
create table if not exists intelligence_kpi_definitions(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),name varchar(160) not null,code varchar(60) not null,description text,category varchar(30) not null check(category in('FINANCE','PRODUCTION','INVENTORY','PROCUREMENT','SALES','EXPORT','FISCAL','LOGISTICS','QUALITY','COMPLIANCE','LIVESTOCK','AGRICULTURE','TRACEABILITY','SUSTAINABILITY','OPERATIONAL','STRATEGIC')),formula varchar(60) not null check(formula in('SUM','COUNT','AVERAGE','PERCENTAGE','BALANCE','MARGIN','PRODUCTIVITY')),data_source varchar(40) not null,periodicity varchar(20) not null check(periodicity in('REAL_TIME','DAILY','WEEKLY','MONTHLY','QUARTERLY','YEARLY')),unit varchar(20) not null check(unit in('NUMBER','CURRENCY','PERCENT','QUANTITY','DAYS','HOURS')),target numeric(20,6),attention_limit numeric(20,6),critical_limit numeric(20,6),active boolean not null default true,strategic boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,unique(tenant_id,id),unique(tenant_id,code),check(unit<>'PERCENT' or (target between 0 and 100 and attention_limit between 0 and 100 and critical_limit between 0 and 100)));
create table if not exists intelligence_kpi_snapshots(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),kpi_id uuid not null,reference_date date not null,calculated_value numeric(20,6),previous_value numeric(20,6),absolute_variation numeric(20,6),percentage_variation numeric(20,6),status varchar(20) not null check(status in('HEALTHY','ATTENTION','CRITICAL','UNAVAILABLE','ERROR')),source varchar(80) not null,calculation_error text,calculated_at timestamptz not null default now(),calculated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,foreign key(tenant_id,kpi_id) references intelligence_kpi_definitions(tenant_id,id),check(status not in('UNAVAILABLE','ERROR') or calculated_value is null));
create table if not exists intelligence_kpi_targets(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),kpi_id uuid not null,value numeric(20,6) not null,valid_from date not null,valid_until date,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,foreign key(tenant_id,kpi_id) references intelligence_kpi_definitions(tenant_id,id),check(valid_until is null or valid_until>=valid_from));
create table if not exists intelligence_alert_rules(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),kpi_id uuid,module varchar(40),name varchar(160) not null,condition varchar(60) not null,operator varchar(30) not null check(operator in('GREATER_THAN','LESS_THAN','EQUAL','NOT_EQUAL','BETWEEN','OUTSIDE_RANGE','OVERDUE','NEAR_DUE','NO_MOVEMENT','DIVERGENT','BLOCKED')),threshold numeric(20,6),threshold_end numeric(20,6),severity varchar(20) not null check(severity in('INFORMATIONAL','ATTENTION','HIGH','CRITICAL')),suggested_action text not null,active boolean not null default true,group_duplicates boolean not null default true,valid_from timestamptz not null,valid_until timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,foreign key(tenant_id,kpi_id) references intelligence_kpi_definitions(tenant_id,id),check(kpi_id is not null or module is not null),check(valid_until is null or valid_until>=valid_from));
create table if not exists intelligence_alerts(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),rule_id uuid,type varchar(40) not null,category varchar(30) not null,severity varchar(20) not null check(severity in('INFORMATIONAL','ATTENTION','HIGH','CRITICAL')),origin varchar(160) not null,source_module varchar(40) not null,related_entity_type varchar(80),related_entity_id uuid,description text not null,recommendation text,status varchar(20) not null default 'NEW' check(status in('NEW','UNDER_REVIEW','ASSIGNED','RESOLVED','IGNORED','CANCELLED')),due_at timestamptz,responsible_id uuid,viewed_by uuid,resolved_by uuid,resolved_at timestamptz,fingerprint varchar(160),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,foreign key(tenant_id,rule_id) references intelligence_alert_rules(tenant_id,id),check(status<>'ASSIGNED' or responsible_id is not null));
create table if not exists intelligence_alert_events(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),alert_id uuid not null,event_type varchar(30) not null,comment text,previous_status varchar(20),new_status varchar(20),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,foreign key(tenant_id,alert_id) references intelligence_alerts(tenant_id,id));
create table if not exists intelligence_risks(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),type varchar(30) not null,source_module varchar(40) not null,cause text not null,severity varchar(20) not null check(severity in('INFORMATIONAL','ATTENTION','HIGH','CRITICAL')),impact text not null,recommendation text not null,detected_at timestamptz not null default now(),status varchar(20) not null default 'OPEN' check(status in('OPEN','MITIGATING','MITIGATED','ACCEPTED','CANCELLED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table if not exists intelligence_recommendations(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),rule_id uuid not null,title varchar(200) not null,description text not null,severity varchar(20) not null check(severity in('INFORMATIONAL','ATTENTION','HIGH','CRITICAL')),source_module varchar(40) not null,related_entity_type varchar(80),related_entity_id uuid,status varchar(20) not null default 'NEW' check(status in('NEW','ANALYSED','ACCEPTED','REJECTED','COMPLETED')),decision_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,deleted_at timestamptz,foreign key(tenant_id,rule_id) references intelligence_alert_rules(tenant_id,id));
create table if not exists intelligence_recommendation_events(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),recommendation_id uuid not null,event_type varchar(30) not null,reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,foreign key(tenant_id,recommendation_id) references intelligence_recommendations(tenant_id,id));
create table if not exists intelligence_audit_events(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),module varchar(40) not null,entity_type varchar(80) not null,entity_id uuid,action varchar(60) not null,previous_value jsonb,new_value jsonb,user_id uuid,ip_address inet,user_agent varchar(500),correlation_id uuid not null,created_at timestamptz not null default now(),created_by uuid);
create table if not exists intelligence_report_exports(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),report varchar(60) not null,filters jsonb not null default '{}',row_count integer not null default 0 check(row_count>=0),created_at timestamptz not null default now(),created_by uuid);
create table if not exists intelligence_user_preferences(id uuid primary key,tenant_id uuid not null references tenancy.tenants(id),user_id uuid not null,dashboard_id uuid,preferences jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid,updated_by uuid,unique(tenant_id,user_id),foreign key(tenant_id,dashboard_id) references intelligence_dashboards(tenant_id,id));
create index if not exists ix_ix_kpi_tenant_category on intelligence_kpi_definitions(tenant_id,category,active) where deleted_at is null;create index if not exists ix_ix_snapshot_history on intelligence_kpi_snapshots(tenant_id,kpi_id,reference_date desc);create index if not exists ix_ix_rules_active on intelligence_alert_rules(tenant_id,active,valid_until,module);create index if not exists ix_ix_alert_queue on intelligence_alerts(tenant_id,status,severity,source_module,created_at desc);create unique index if not exists ux_ix_alert_fingerprint on intelligence_alerts(tenant_id,fingerprint) where fingerprint is not null and status in('NEW','UNDER_REVIEW','ASSIGNED');create index if not exists ix_ix_risk_radar on intelligence_risks(tenant_id,status,severity,type,detected_at desc);create index if not exists ix_ix_recommendation_queue on intelligence_recommendations(tenant_id,status,severity,source_module,created_at desc);create index if not exists ix_ix_audit_timeline on intelligence_audit_events(tenant_id,module,created_at desc,correlation_id);
do $$ declare tab text; begin for tab in select unnest(array['intelligence_dashboards','intelligence_kpi_definitions','intelligence_kpi_snapshots','intelligence_kpi_targets','intelligence_alert_rules','intelligence_alerts','intelligence_alert_events','intelligence_risks','intelligence_recommendations','intelligence_recommendation_events','intelligence_audit_events','intelligence_report_exports','intelligence_user_preferences']) loop execute format('alter table %I enable row level security',tab);execute format('alter table %I force row level security',tab);if not exists(select 1 from pg_policies where schemaname='public' and tablename=tab and policyname=tab||'_tenant') then execute format('create policy %I on %I using (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) with check (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',tab||'_tenant',tab);end if;end loop;end $$;
insert into identity.permissions(code,module,description) values('intelligence.strategic','Inteligência Agro360','Gerenciar indicadores estratégicos.'),('intelligence.export','Inteligência Agro360','Exportar relatórios executivos.') on conflict(code) do update set module=excluded.module,description=excluded.description;
insert into platform.schema_versions(version,description,installed_at) values('4.1.0','Sprint 41 - Inteligencia executiva e BI operacional',now()) on conflict(version) do nothing;
commit;
